<#
.SYNOPSIS
    [Intune Script] Windows - National Minute of Silence Reminder
    Розгортає щоденне нагадування про загальнонаціональну хвилину мовчання о 09:00 для Windows-ноутбуків.

.DESCRIPTION
    Цей скрипт призначений для завантаження в Microsoft Intune (Devices > Scripts > Windows).
    - Налаштування Intune:
        * Run this script using the logged on credentials: Yes (RunAsAccount: user)
        * Enforce script signature check: No
        * Run script in 64-bit PowerShell: Yes
    - Дії:
        1. Розгортає WPF-скрипт показу сповіщення в %LOCALAPPDATA%\Corporate\MinuteOfSilence.
        2. Створює щоденне завдання Windows Task Scheduler на 09:00:00 за місцевим часом.
        3. Забезпечує коректну роботу від батареї, захист від повторного запуску, звук та Time Guard.

.NOTES
    Відповідає вимогам Jira II-5426 та корпоративним стандартам назв Intune:
    "Windows - <Action / Purpose>"
#>
[CmdletBinding()]
param()

$ErrorActionPreference = 'Stop'

Write-Host "=== [Intune] Windows - National Minute of Silence Reminder ===" -ForegroundColor Cyan

# ── 1. Визначення цільової директорії ─────────────────────────────────────────
$InstallDir = Join-Path $env:LOCALAPPDATA "Corporate\MinuteOfSilence"
if (-not $env:LOCALAPPDATA -or $env:USERNAME -eq "SYSTEM") {
    $InstallDir = "C:\ProgramData\Corporate\MinuteOfSilence"
}

if (-not (Test-Path $InstallDir)) {
    New-Item -Path $InstallDir -ItemType Directory -Force | Out-Null
    Write-Host "Створено директорію: $InstallDir" -ForegroundColor Gray
}

$PayloadPath = Join-Path $InstallDir "Show-MinuteOfSilence.ps1"
$AudioPath   = Join-Path $InstallDir "metronome.mp3"
$AudioUrl    = "https://raw.githubusercontent.com/girilovsky/National-Minute-Of-Silence/main/windows/metronome.mp3"
$TaskName    = "National Minute of Silence Reminder"

# Завантаження та локальне кешування аудіотреку з GitHub
if (-not (Test-Path $AudioPath) -or (Get-Item $AudioPath).Length -lt 100000) {
    try {
        Write-Host "Завантаження студійного аудіотреку з GitHub ($AudioUrl)..." -ForegroundColor Cyan
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        Invoke-WebRequest -Uri $AudioUrl -OutFile $AudioPath -UseBasicParsing -TimeoutSec 15
        Write-Host "Аудіотрек завантажено: $AudioPath" -ForegroundColor Green
    } catch {
        Write-Warning "Не вдалося завантажити аудіотрек: $_. Буде використано синтез."
    }
}

# ── 2. Запис бінарного/Base64 пейлоаду ─────────────────────────────────────────
$PayloadB64 = @"

"@

$payloadBytes = [System.Convert]::FromBase64String($PayloadB64.Trim())
[System.IO.File]::WriteAllBytes($PayloadPath, $payloadBytes)
Write-Host "Пейлоад записано: $PayloadPath" -ForegroundColor Green

# ── 3. Створення завдання планувальника Windows ────────────────────────────────
Write-Host "Реєстрація щоденного завдання '$TaskName' на 09:00..." -ForegroundColor Cyan

$action = New-ScheduledTaskAction `
    -Execute "powershell.exe" `
    -Argument "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$PayloadPath`""

$trigger = New-ScheduledTaskTrigger -Daily -At "08:59:50"

$settings = New-ScheduledTaskSettingsSet `
    -AllowStartIfOnBatteries `
    -DontStopIfGoingOnBatteries `
    -ExecutionTimeLimit (New-TimeSpan -Minutes 2) `
    -MultipleInstances IgnoreNew

$existingTask = Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue
if ($existingTask) {
    Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false
}

$registeredTask = Register-ScheduledTask `
    -TaskName $TaskName `
    -Action $action `
    -Trigger $trigger `
    -Settings $settings `
    -Description "Щоденне сповіщення про загальнонаціональну хвилину мовчання о 09:00" `
    -Force

Write-Host "УСПІШНО: Завдання '$TaskName' зареєстровано. Наступний запуск о 09:00." -ForegroundColor Green
exit 0